with valid_suppliers as (select * from suppliers where supplier_name like 'T%'), summary as (select case when city in ('Singapore', 'Chiang Mai') then 'group_a' else 'other' end as city_group, city, round(stddev(rating), 2) as stddev_rating from valid_suppliers group by case when city in ('Singapore', 'Chiang Mai') then 'group_a' else 'other' end, city) select city_group, city, stddev_rating from summary where stddev_rating > 65;
